(() => {
  const CFG = window.RIPPLEGUARD_CONFIG || { API_BASE: "http://127.0.0.1:5000" };
  const API = String(CFG.API_BASE || "").replace(/\/$/, "");
  const $ = (s, root=document) => root.querySelector(s);
  const $$ = (s, root=document) => [...root.querySelectorAll(s)];
  const state = { token: sessionStorage.getItem("rg_token"), user: JSON.parse(sessionStorage.getItem("rg_user") || "null"), page: "dashboard", dashboard: null, data: {}, notifications: [], otpEmail: "", otpSeconds: 180, otpTimer: null, sound: true, map: null, lastPlan: null, lastAnalysis: null, modalSubmit: null };
  const esc = v => String(v ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const fmt = n => Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
  const money = n => "₹" + Number(n || 0).toLocaleString("en-IN", { maximumFractionDigits: 2 });
  const titleCase = s => String(s || "").replace(/[_-]/g," ").replace(/\b\w/g, c=>c.toUpperCase());
  const rolePages = {
    "Admin": ["dashboard","network","suppliers","facilities","products","disruptions","impact","recovery","reports"],
    "Supply Chain Manager": ["dashboard","network","suppliers","products","disruptions","impact","simulator","recovery","reports"],
    "Procurement Officer": ["dashboard","suppliers","products","recovery","reports"],
    "Warehouse Manager": ["dashboard","facilities","products","disruptions","reports"],
    "Risk Analyst": ["dashboard","disruptions","impact","simulator","recovery","validation","reports"],
    "Supplier": ["dashboard","products","disruptions"]
  };
  const allowedPages = () => rolePages[state.user?.role] || rolePages["Supply Chain Manager"];
  const canWrite = p => { const r = state.user?.role; if (["Admin","Supply Chain Manager"].includes(r)) return true; if (r === "Procurement Officer") return ["suppliers","products","orders"].includes(p); if (r === "Warehouse Manager") return ["facilities","products","orders","disruptions"].includes(p); if (r === "Supplier") return ["disruptions","orders"].includes(p); return false; };
  const pageNames = {dashboard:"Command center",network:"Supply network",disruptions:"Disruptions",suppliers:"Suppliers",facilities:"Facilities & locations",products:"Products & orders",production:"Production journey",impact:"Impact analysis",simulator:"What-if simulator",recovery:"Recovery planner",validation:"Plan validation",reports:"Reports & history",settings:"Workspace settings"};

  async function api(path, options={}) {
    const headers = { ...(options.headers || {}) };
    if (options.body && !(options.body instanceof FormData)) headers["Content-Type"] = "application/json";
    if (state.token) headers.Authorization = `Bearer ${state.token}`;
    let response;
    try { response = await fetch(`${API}${path}`, { ...options, headers }); }
    catch (_) { throw new Error(`Cannot reach the API at ${API || "this website"}. Start the Flask backend and check frontend/config.js.`); }
    const ct = response.headers.get("content-type") || "";
    const data = ct.includes("application/json") ? await response.json() : response;
    if (!response.ok) throw new Error(data.error || data.message || `Request failed (${response.status})`);
    return data;
  }
  function toast(title, message, type="success") {
    const el = document.createElement("div"); el.className="toast";
    el.innerHTML=`<span class="toast-icon">${type==="error"?"!":type==="warning"?"△":"✓"}</span><div><b>${esc(title)}</b><p>${esc(message)}</p></div>`;
    $("#toastStack").appendChild(el); if(state.sound) playTone(type==="error"?220:680, type==="error"?0.16:0.09);
    setTimeout(()=>{el.style.opacity="0";el.style.transform="translateX(12px)";setTimeout(()=>el.remove(),250)},4200);
  }
  function playTone(freq=680, duration=.1) { try { const Ctx=window.AudioContext||window.webkitAudioContext; const ctx=new Ctx(); const osc=ctx.createOscillator(), gain=ctx.createGain(); osc.type="sine";osc.frequency.value=freq;gain.gain.value=.035;osc.connect(gain);gain.connect(ctx.destination);osc.start();gain.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+duration);osc.stop(ctx.currentTime+duration);osc.onended=()=>ctx.close(); } catch(_){} }
  function setAuthTab(tab) { ["login","register","otp"].forEach(k=>$("#"+k+"FormWrap").classList.toggle("hidden",k!==tab)); $$(".auth-tab").forEach(b=>b.classList.toggle("active",b.dataset.authTab===tab)); }
  function showAuth(tab="login") { $("#authView").classList.remove("hidden"); $("#appView").classList.add("hidden"); setAuthTab(tab); }
  function enterApp(user) {
    state.user=user; sessionStorage.setItem("rg_user",JSON.stringify(user)); $("#authView").classList.add("hidden"); $("#appView").classList.remove("hidden");
    $("#workspaceName").textContent=user.company||"My Workspace"; $("#userNameSide").textContent=user.name||"User"; $("#userRoleSide").textContent=user.role||"Member"; $("#topUserName").textContent=user.name||"User"; $("#topUserRole").textContent=user.role||"Member"; $("#userAvatar").textContent=(user.name||"U").trim().charAt(0).toUpperCase(); $("#topAvatar").textContent=(user.name||"U").trim().charAt(0).toUpperCase();
    const allowed=rolePages[user.role]||rolePages["Supply Chain Manager"];
    $$(".nav-item[data-page]").forEach(b=>{b.classList.toggle("hidden",!allowed.includes(b.dataset.page));});
    const now=new Date(); $("#currentDate").textContent=now.toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric",year:"numeric"})+" · Supply chain visibility, all in one place.";
    loadNotifications(); navigate("dashboard"); startLive(); speak(`Welcome ${user.name}. You are signed in as ${user.role}.`);
  }
  function logout() { stopLive();state.token=null;state.user=null;sessionStorage.removeItem("rg_token");sessionStorage.removeItem("rg_user");state.data={};if(state.map){state.map.remove();state.map=null;}showAuth("login");toast("Signed out","Your session has ended.","success"); }

  // Registration and OTP verification
  $("#loginForm").addEventListener("submit",async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent="Signing in…";try{const d=await api("/api/auth/login",{method:"POST",body:JSON.stringify({identifier:$("#loginEmail").value,password:$("#loginPassword").value})});state.token=d.token;sessionStorage.setItem("rg_token",d.token);enterApp(d.user);toast("Welcome back",`Signed in as ${d.user.name}.`);}catch(err){toast("Sign-in failed",err.message,"error");}finally{btn.disabled=false;btn.innerHTML='Sign in <span>→</span>';}});
  $("#registerForm").addEventListener("submit",async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent="Preparing verification…";try{const payload={name:$("#regName").value.trim(),company:$("#regCompany").value.trim(),email:$("#regEmail").value.trim(),phone:$("#regPhone").value.trim(),role:$("#regRole").value,password:$("#regPassword").value};const d=await api("/api/auth/register",{method:"POST",body:JSON.stringify(payload)});state.otpEmail=payload.email;state.otpSeconds=d.expires_in||180;$("#demoSms").classList.toggle("hidden",!d.demo_otp);$("#demoOtpValue").textContent=d.demo_otp||"SMS provider not configured";$("#otpInput").value="";setAuthTab("otp");startOtpTimer();toast("Verification code ready",d.notice||"Enter the one-time code to continue.");}catch(err){toast("Registration failed",err.message,"error");}finally{btn.disabled=false;btn.innerHTML='Create account <span>→</span>';}});
  $("#otpForm").addEventListener("submit",async e=>{e.preventDefault();try{await api("/api/auth/verify-otp",{method:"POST",body:JSON.stringify({email:state.otpEmail,otp:$("#otpInput").value.trim()})});clearInterval(state.otpTimer);$("#loginEmail").value=state.otpEmail;$("#loginPassword").value="";setAuthTab("login");toast("Account verified","Now sign in using your email and password.");}catch(err){toast("Verification failed",err.message,"error");}});
  function startOtpTimer(){clearInterval(state.otpTimer);const tick=()=>{const m=String(Math.floor(state.otpSeconds/60)).padStart(2,"0"),s=String(state.otpSeconds%60).padStart(2,"0");$("#otpTimer").textContent=`${m}:${s}`;if(state.otpSeconds<=0){clearInterval(state.otpTimer);$("#otpTimer").textContent="Expired";$("#otpTimer").style.color="var(--red)";}else state.otpSeconds--;};tick();state.otpTimer=setInterval(tick,1000);}
  document.addEventListener("click",e=>{const tab=e.target.closest("[data-auth-tab]");if(tab)setAuthTab(tab.dataset.authTab);const sw=e.target.closest("[data-switch-auth]");if(sw)setAuthTab(sw.dataset.switchAuth);const tog=e.target.closest("[data-toggle-password]");if(tog){const input=$("#"+tog.dataset.togglePassword);input.type=input.type==="password"?"text":"password";tog.textContent=input.type==="password"?"Show":"Hide";}});
  $("#cancelOtp").addEventListener("click",()=>{clearInterval(state.otpTimer);setAuthTab("register")});$("#logoutBtn").addEventListener("click",logout);

  // Navigation, mobile sidebar, sound, notifications
  $$(".nav-item[data-page]").forEach(btn=>btn.addEventListener("click",()=>{if(!btn.classList.contains("hidden"))navigate(btn.dataset.page);closeMobileNav();}));
  function navigate(page){if(!(rolePages[state.user?.role]||rolePages["Supply Chain Manager"]).includes(page))page="dashboard";state.page=page;$$(".nav-item[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===page));$("#breadcrumbPage").textContent=pageNames[page]||page; if(state.map){state.map.remove();state.map=null;}renderPage(page);}
  $("#openSidebar").addEventListener("click",()=>{$("#sidebar").classList.add("open");$("#sidebarScrim").classList.add("show")});$("#closeSidebar").addEventListener("click",closeMobileNav);$("#sidebarScrim").addEventListener("click",closeMobileNav);function closeMobileNav(){$("#sidebar").classList.remove("open");$("#sidebarScrim").classList.remove("show")}
  $("#soundToggle").addEventListener("click",()=>{state.sound=!state.sound;$("#soundToggle").style.color=state.sound?"var(--teal-deep)":"#a0aab1";toast("Notification sound",state.sound?"Sound is enabled.":"Sound is muted.");if(state.sound)playTone()});
  $("#notificationBtn").addEventListener("click",e=>{e.stopPropagation();$("#notificationPanel").classList.toggle("hidden");});document.addEventListener("click",e=>{if(!e.target.closest(".notification-wrap"))$("#notificationPanel").classList.add("hidden")});$("#markAllRead").addEventListener("click",async()=>{try{await api("/api/notifications/read-all",{method:"POST"});await loadNotifications();toast("Notifications updated","All notifications marked as read.");}catch(e){toast("Could not update",e.message,"error")}});
  async function loadNotifications(){if(!state.token)return;try{const d=await api("/api/notifications");state.notifications=d.items||[];const unread=d.unread||0;$("#notificationBadge").textContent=unread;$("#notificationBadge").classList.toggle("hidden",unread===0);$("#notificationSub").textContent=unread?`${unread} unread update${unread===1?"":"s"}`:"You're all caught up";$("#notificationList").innerHTML=state.notifications.length?state.notifications.map(n=>`<div class="notification-row ${n.read?"":"unread"}" data-notification-id="${esc(n.id)}"><span class="notification-dot"></span><div><b>${esc(n.title)}</b><p>${esc(n.message)}</p><small>${esc(timeAgo(n.created_at))}</small></div></div>`).join(""):`<div class="empty-notifications">No notifications yet. Actions in your workspace will appear here.</div>`;$$('[data-notification-id]').forEach(el=>el.addEventListener("click",async()=>{try{await api(`/api/notifications/${el.dataset.notificationId}/read`,{method:"PATCH",body:JSON.stringify({})});await loadNotifications();}catch(_){}}));}catch(_){}}
  function timeAgo(date){if(!date)return"just now";const ms=Date.now()-new Date(date).getTime(),m=Math.max(0,Math.floor(ms/60000));return m<1?"just now":m<60?`${m} min ago`:m<1440?`${Math.floor(m/60)} hr ago`:new Date(date).toLocaleDateString();}

  async function getCollection(name){const d=await api(`/api/${name}`);state.data[name]=d.items||[];return state.data[name];}
  async function loadAll(){const names=["suppliers","facilities","products","orders","disruptions","process_steps"];await Promise.all(names.map(n=>getCollection(n).catch(()=>state.data[n]||[])));}
  async function renderPage(page){const root=$("#pageContent");root.innerHTML=`<div class="loading-state"><div class="loader"></div><p>Loading ${esc(pageNames[page]||page)}…</p></div>`;try{if(page==="dashboard"){const d=await api("/api/dashboard");state.dashboard=d;state.data.suppliers=d.suppliers;state.data.facilities=d.facilities;state.data.products=d.products;state.data.orders=d.orders;state.data.disruptions=d.disruptions;root.innerHTML=dashboardHTML(d);bindDashboard();}
      else if(["suppliers","facilities","products","disruptions"].includes(page)){await getCollection(page);if(page==="products")await getCollection("orders");root.innerHTML=collectionHTML(page);bindCollection(page);}
      else if(page==="production"){await loadAll();root.innerHTML=productionHTML();bindProduction();}
      else if(page==="network"){await loadAll();root.innerHTML=networkHTML();setTimeout(initMap,50);bindNetwork();}
      else if(page==="impact"){const d=await api("/api/dashboard");state.dashboard=d;root.innerHTML=impactHTML(d);bindImpact();}
      else if(page==="simulator"){await loadAll();root.innerHTML=simulatorHTML();bindSimulator();}
      else if(page==="recovery"){await loadAll();root.innerHTML=recoveryHTML();bindRecovery();}
      else if(page==="validation"){root.innerHTML=validationHTML();bindValidation();}
      else if(page==="reports"){const d=await api("/api/analyses/history");root.innerHTML=reportsHTML(d.items||[]);bindReports();}
      else if(page==="settings"){root.innerHTML=settingsHTML();bindSettings();}
    }catch(err){root.innerHTML=`<div class="card card-pad"><h3 class="card-title">Unable to load this page</h3><p class="muted">${esc(err.message)}</p><button class="btn btn-primary" id="retryPage">Retry</button></div>`;$("#retryPage").addEventListener("click",()=>navigate(page));}}

  function pageHead(title,desc,actions=""){return `<div class="page-heading"><div><div class="section-eyebrow">RIPPLEGUARD / ${esc(title.toUpperCase())}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><div class="heading-actions">${actions}</div></div>`}
  function metric(label,value,icon,foot,idx=0){return `<div class="card metric-card"><div class="metric-top"><span class="metric-label">${esc(label)}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${esc(value)}</div><div class="metric-foot">${foot}</div><span class="metric-spark"></span></div>`}
  function riskPill(level){const cls=level==="Critical"?"critical":level==="Warning"?"warning":"";return `<span class="status-pill ${cls}">${esc(level||"Stable")}</span>`}
  function emptyRow(cols,msg="No records yet. Add your first record to get started."){return `<tr><td colspan="${cols}" class="empty-row">${esc(msg)}</td></tr>`}
  function dashboardHTML(d){const score=d.risk_score||0,circ=2*Math.PI*49,offset=circ-(score/100)*circ;const disruptions=(d.disruptions||[]).slice(0,4);const orders=(d.recent_orders||[]).slice(0,4);const bars=[{l:"Suppliers",v:d.supplier_count},{l:"Facilities",v:d.facility_count},{l:"Products",v:d.product_count},{l:"Orders",v:d.order_count},{l:"Events",v:d.active_disruptions}];const max=Math.max(1,...bars.map(x=>x.v));return `${pageHead("Command center","A clear view of network health, operational exposure, and recovery readiness.",`<button class="btn btn-outline" id="dashRefresh">↻ Refresh</button>${(d.supplier_count+d.facility_count+d.product_count+d.order_count+d.active_disruptions)===0?`<button class="btn btn-outline" id="loadDemoData">Load demo workspace</button>`:""}<button class="btn btn-primary" id="dashRun">Run impact analysis →</button>`)}
    <div class="metric-grid">${metric("Registered suppliers",fmt(d.supplier_count),"⇄","<strong>Network</strong> · supply sources")}${metric("Facilities & sites",fmt(d.facility_count),"⌂","Factories, hubs and warehouses")}${metric("Active disruptions",fmt(d.active_disruptions),"⌁",d.active_disruptions?"<strong style='color:#bf7b27'>Needs review</strong>":"No active incident recorded")}${metric("Estimated shortage",fmt(d.shortage),"▦",`Required ${fmt(d.total_required)} · Stock ${fmt(d.total_stock)}`)}</div>
    <div class="dashboard-grid"><section class="card card-pad risk-card"><div class="card-head"><div><h3 class="card-title">Network risk pulse</h3><div class="card-subtitle">Live score from your team's records</div></div>${riskPill(d.risk_level)}</div><div class="risk-row"><div class="risk-ring"><svg viewBox="0 0 110 110"><circle class="ring-track" cx="55" cy="55" r="49"></circle><circle class="ring-value" cx="55" cy="55" r="49" stroke-dasharray="${circ}" stroke-dashoffset="${offset}"></circle></svg><div class="risk-ring-label"><b>${score}</b><small>OF 100</small></div></div><div class="risk-details"><h3>${score>=70?"High exposure detected":score>=35?"Attention needed":"Network looks stable"}</h3><p>${d.active_disruptions?`${d.active_disruptions} active disruption(s) are recorded. Review affected suppliers and validate a recovery path.`:"Record a disruption to test how it could affect your supply chain."}</p><span class="status-pill ${d.risk_level==="Critical"?"critical":d.risk_level==="Warning"?"warning":""}">${esc(d.risk_level)} risk</span></div></div><div class="risk-action"><span>Updates automatically when any role adds data.</span><button id="riskExplore">Explore analysis ↗</button></div></section>
    <section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Quick actions</h3><div class="card-subtitle">Move from data to a decision</div></div></div><div class="quick-actions"><button class="quick-action" data-quick="suppliers"><span class="qa-icon">⇄</span><b>Add supplier</b><small>Register a supply source</small></button><button class="quick-action" data-quick="disruptions"><span class="qa-icon">⌁</span><b>Log disruption</b><small>Record a new incident</small></button><button class="quick-action" data-quick="simulator"><span class="qa-icon">◉</span><b>Run scenario</b><small>Test a what-if event</small></button><button class="quick-action" data-quick="recovery"><span class="qa-icon">↗</span><b>Plan recovery</b><small>Compare supplier options</small></button></div></section></div>
    <div class="dashboard-bottom"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Recent disruptions</h3><div class="card-subtitle">Latest incidents registered in this workspace</div></div><button class="small-link" data-go="disruptions">View all →</button></div><div class="table-wrap"><table><thead><tr><th>Incident</th><th>Affected supplier</th><th>Severity</th><th>Status</th></tr></thead><tbody>${disruptions.length?disruptions.map(x=>`<tr><td><div class="table-primary">${esc(x.name)}</div><div class="table-secondary">${esc(x.type||"Disruption")}</div></td><td>${esc(x.affected_supplier||"Not assigned")}</td><td>${riskPill(x.severity||"Medium")}</td><td>${riskPill(x.status||"Active")}</td></tr>`).join(""):emptyRow(4,"No disruptions recorded yet.")}</tbody></table></div></section>
    <section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Workspace footprint</h3><div class="card-subtitle">Records currently available to analyze</div></div></div><div class="bar-chart">${bars.map(x=>`<div class="bar-column"><span class="bar-value">${fmt(x.v)}</span><div class="bar" style="height:${Math.max(5,x.v/max*75)}%"></div><span class="bar-label">${x.l}</span></div>`).join("")}</div><div class="notice-box" style="margin-top:18px">${d.supplier_count===0?"Start by adding suppliers, then add facilities and stock data.":`Your workspace has ${fmt(d.supplier_count+d.facility_count+d.product_count+d.order_count)} core records ready for planning.`}</div></section></div>`;}
  function bindDashboard(){ const ap=allowedPages();$$('[data-quick]').forEach(b=>{if(!ap.includes(b.dataset.quick))b.remove()});["dashRun","riskExplore"].forEach(id=>{if(!ap.includes("impact"))$("#"+id).classList.add("hidden")});const sd=$("#loadDemoData");if(sd&&!["Admin","Supply Chain Manager"].includes(state.user.role))sd.remove(); $("#dashRefresh").addEventListener("click",()=>renderPage("dashboard"));const seed=$("#loadDemoData");if(seed)seed.addEventListener("click",async()=>{seed.disabled=true;seed.textContent="Loading…";try{await api("/api/demo/seed",{method:"POST",body:JSON.stringify({})});toast("Demo workspace loaded","Illustrative suppliers, facilities, products, orders and disruption added.");await renderPage("dashboard");loadNotifications();}catch(e){toast("Could not load demo data",e.message,"error");seed.disabled=false;seed.textContent="Load demo workspace"}});$("#dashRun").addEventListener("click",async()=>{try{const d=await api("/api/analysis/run",{method:"POST",body:JSON.stringify({})});state.lastAnalysis=d;toast("Analysis complete",`Risk score ${d.risk_score}/100 · ${d.risk_level}`,d.risk_score>=35?"warning":"success");navigate("impact");}catch(e){toast("Analysis failed",e.message,"error")}});$("#riskExplore").addEventListener("click",()=>navigate("impact"));$$('[data-quick]').forEach(b=>b.addEventListener("click",()=>{const p=b.dataset.quick;if(["suppliers","disruptions"].includes(p)){navigate(p);setTimeout(()=>openRecordModal(p),80)}else navigate(p)}));$$('[data-go]').forEach(b=>b.addEventListener("click",()=>navigate(b.dataset.go))); }

  const collectionMeta={suppliers:{title:"Suppliers",desc:"Manage supply partners, capacity, unit cost, lead time and reliability.",icon:"⇄",fields:[{k:"name",l:"Supplier name",req:1},{k:"category",l:"Material / category",placeholder:"e.g. Electronic components"},{k:"contact",l:"Contact person"},{k:"email",l:"Contact email",type:"email"},{k:"phone",l:"Phone"},{k:"capacity",l:"Daily capacity (units)",type:"number",req:1},{k:"unit_cost",l:"Unit cost (₹)",type:"number",req:1},{k:"lead_days",l:"Lead time (days)",type:"number",req:1},{k:"reliability",l:"Reliability (%)",type:"number",req:1},{k:"latitude",l:"Latitude",type:"number",placeholder:"11.0168"},{k:"longitude",l:"Longitude",type:"number",placeholder:"76.9558"},{k:"status",l:"Status",type:"select",options:["Active","At risk","Inactive"]}]},facilities:{title:"Facilities & locations",desc:"Map factories, warehouses and hubs with geographic coordinates.",icon:"⌂",fields:[{k:"name",l:"Facility name",req:1},{k:"type",l:"Facility type",type:"select",options:["Factory","Warehouse","Distribution hub","Port","Store"]},{k:"address",l:"Address / city",req:1},{k:"latitude",l:"Latitude",type:"number",req:1,placeholder:"11.0168"},{k:"longitude",l:"Longitude",type:"number",req:1,placeholder:"76.9558"},{k:"capacity",l:"Daily handling capacity",type:"number"},{k:"contact",l:"Contact person"},{k:"status",l:"Status",type:"select",options:["Operational","At risk","Closed"]}]},products:{title:"Products & orders",desc:"Track products, required components, available stock, and delivery commitments.",icon:"▦",fields:[{k:"name",l:"Product / item name",req:1},{k:"sku",l:"SKU / product code"},{k:"category",l:"Category"},{k:"required_components",l:"Required components",type:"number",req:1},{k:"available_stock",l:"Available stock",type:"number",req:1},{k:"priority",l:"Priority",type:"select",options:["Low","Medium","High","Critical"]},{k:"unit",l:"Unit",placeholder:"pieces / kg / boxes"},{k:"target_date",l:"Target completion date",type:"date"}]},disruptions:{title:"Disruptions",desc:"Record supplier failures, transport delays, weather incidents, and their severity.",icon:"⌁",fields:[{k:"name",l:"Incident title",req:1},{k:"type",l:"Disruption type",type:"select",options:["Supplier shutdown","Transport delay","Flood / weather","Material shortage","Port closure","Quality issue","Other"]},{k:"affected_supplier",l:"Affected supplier name",placeholder:"Match a supplier in your list"},{k:"location",l:"Affected location"},{k:"severity",l:"Severity",type:"select",options:["Low","Medium","High","Critical"]},{k:"status",l:"Status",type:"select",options:["Active","Monitoring","Resolved"]},{k:"start_date",l:"Start date and time",type:"datetime-local"},{k:"expected_days",l:"Expected duration (days)",type:"number"},{k:"description",l:"Description / evidence",type:"textarea",full:1}]}};
  function collectionHTML(page){const m=collectionMeta[page],items=state.data[page]||[];let table="";if(page==="suppliers")table=`<thead><tr><th>Supplier</th><th>Material</th><th>Capacity / day</th><th>Unit cost</th><th>Lead time</th><th>Reliability</th><th>Status</th><th></th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td><div class="table-primary">${esc(x.name)}</div><div class="table-secondary">${esc(x.contact||x.email||"No contact")}</div></td><td>${esc(x.category||"—")}</td><td>${fmt(x.capacity)}</td><td>${money(x.unit_cost)}</td><td>${fmt(x.lead_days)} days</td><td>${fmt(x.reliability)}%</td><td>${riskPill(x.status||"Active")}</td><td><button class="table-action" data-edit="${esc(x.id)}">Edit</button> <button class="table-action" data-delete="${esc(x.id)}">Delete</button></td></tr>`).join(""):emptyRow(8,"No suppliers yet. Add a supplier to build your network.")}</tbody>`;
    else if(page==="facilities")table=`<thead><tr><th>Facility</th><th>Type</th><th>Address</th><th>Coordinates</th><th>Capacity</th><th>Status</th><th></th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td><div class="table-primary">${esc(x.name)}</div></td><td>${esc(x.type||"Factory")}</td><td>${esc(x.address||"—")}</td><td>${fmt(x.latitude)}, ${fmt(x.longitude)}</td><td>${fmt(x.capacity)}</td><td>${riskPill(x.status||"Operational")}</td><td><button class="table-action" data-edit="${esc(x.id)}">Edit</button> <button class="table-action" data-delete="${esc(x.id)}">Delete</button></td></tr>`).join(""):emptyRow(7,"No facilities yet. Add locations to see them on the map.")}</tbody>`;
    else if(page==="products")table=`<thead><tr><th>Product</th><th>Required</th><th>Available</th><th>Shortage</th><th>Priority</th><th>Target date</th><th></th></tr></thead><tbody>${items.length?items.map(x=>{const sh=Math.max(0,Number(x.required_components||0)-Number(x.available_stock||0));return `<tr><td><div class="table-primary">${esc(x.name)}</div><div class="table-secondary">${esc(x.sku||x.category||"No SKU")}</div></td><td>${fmt(x.required_components)}</td><td>${fmt(x.available_stock)}</td><td>${sh?`<span style="color:#bd6b39;font-weight:800">${fmt(sh)}</span>`:"0"}</td><td>${riskPill(x.priority||"Medium")}</td><td>${esc(x.target_date||"—")}</td><td><button class="table-action" data-edit="${esc(x.id)}">Edit</button> <button class="table-action" data-delete="${esc(x.id)}">Delete</button></td></tr>`}).join(""):emptyRow(7,"No products yet. Add required quantities and available stock.")}</tbody>`;
    else table=`<thead><tr><th>Incident</th><th>Type</th><th>Supplier / location</th><th>Severity</th><th>Start</th><th>Status</th><th></th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td><div class="table-primary">${esc(x.name)}</div><div class="table-secondary">${esc(x.description||"No description")}</div></td><td>${esc(x.type||"Other")}</td><td>${esc(x.affected_supplier||x.location||"—")}</td><td>${riskPill(x.severity||"Medium")}</td><td>${esc(x.start_date||"—")}</td><td>${riskPill(x.status||"Active")}</td><td><button class="table-action" data-edit="${esc(x.id)}">Edit</button> <button class="table-action" data-delete="${esc(x.id)}">Delete</button></td></tr>`).join(""):emptyRow(7,"No disruptions logged. Record an incident to run impact analysis.")}</tbody>`;
    const side=page==="suppliers"?`<div class="notice-box">Supplier scoring uses daily capacity, unit cost, lead time, and reliability. These inputs feed the recovery planner.</div>`:page==="facilities"?`<div class="notice-box">Enter real latitude and longitude to place a facility on the interactive map. OpenStreetMap tiles are used in this prototype.</div>`:page==="products"?`<div class="notice-box">Stock gaps are calculated from the quantities you enter.</div>`:`<div class="notice-box amber">Only mark an incident as Resolved when your team has confirmed the disruption has ended. Analysis uses Active incidents.</div>`;
    return `${pageHead(m.title,m.desc,`<button class="btn btn-outline" id="exportCurrent">Export CSV</button><button class="btn btn-primary" id="addRecord">+ Add ${page==="products"?"product":page==="disruptions"?"disruption":page.slice(0,-1)}</button>`)}<div class="content-grid"><section class="card card-pad data-table-card"><div class="card-head"><div><h3 class="card-title">${esc(m.title)} register</h3><div class="card-subtitle">${items.length} record${items.length===1?"":"s"} · changes are saved to your workspace</div></div><span class="status-pill">Live workspace</span></div><div class="table-tools"><input class="search-input" id="tableSearch" placeholder="Search ${m.title.toLowerCase()}…" /><span class="muted">Use Edit to update a record</span></div><div class="table-wrap"><table id="recordsTable">${table}</table></div></section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Quick tips</h3><div class="card-subtitle">Keep records accurate</div></div></div>${side}</aside></div>`;}
  function bindCollection(page){if(!canWrite(page)){const a=$("#addRecord");if(a)a.classList.add("hidden");} $("#addRecord").addEventListener("click",()=>openRecordModal(page));$("#exportCurrent").addEventListener("click",()=>exportCsv(page));const search=$("#tableSearch");search.addEventListener("input",()=>{$$("#recordsTable tbody tr").forEach(tr=>tr.style.display=tr.textContent.toLowerCase().includes(search.value.toLowerCase())?"":"none")});$$('[data-delete]').forEach(btn=>btn.addEventListener("click",async()=>{const item=(state.data[page]||[]).find(x=>x.id===btn.dataset.delete);if(!confirm(`Delete ${item?.name||"this record"}?`))return;try{await api(`/api/${page}/${btn.dataset.delete}`,{method:"DELETE"});toast("Record deleted","The record was removed from this workspace.");renderPage(page);loadNotifications();}catch(e){toast("Delete failed",e.message,"error")}}));$$('[data-edit]').forEach(btn=>btn.addEventListener("click",()=>openRecordModal(page,(state.data[page]||[]).find(x=>x.id===btn.dataset.edit))));}
  function fieldHTML(f,val=""){const req=f.req?"required":"",full=f.full?"full":"";let control;if(f.type==="select")control=`<select class="field-control" name="${f.k}" ${req}>${f.options.map(o=>`<option ${String(val)===o?"selected":""}>${o}</option>`).join("")}</select>`;else if(f.type==="textarea")control=`<textarea class="field-control" name="${f.k}" rows="3" placeholder="${esc(f.placeholder||"")}" ${req}>${esc(val)}</textarea>`;else control=`<input class="field-control" name="${f.k}" type="${f.type||"text"}" value="${esc(val)}" placeholder="${esc(f.placeholder||"")}" ${f.type==="number"?'step="any"':''} ${req} />`;return `<label class="field-label ${full}">${esc(f.l)}${control}</label>`;}
  function openRecordModal(page,item=null){const m=collectionMeta[page];const body=`<form id="recordForm"><div class="form-grid">${m.fields.map(f=>fieldHTML(f,item?.[f.k]??"")).join("")}</div><div class="form-actions"><button type="button" class="btn btn-outline" id="cancelRecord">Cancel</button><button type="submit" class="btn btn-primary">${item?"Save changes":"Save record"} →</button></div></form>`;openModal(`${item?"Edit":"Add"} ${page==="products"?"product":page==="disruptions"?"disruption":page.slice(0,-1)}`,`Enter accurate data for your ${page.slice(0,-1)} record`,body,[]);$("#cancelRecord").addEventListener("click",closeModal);$("#recordForm").addEventListener("submit",async e=>{e.preventDefault();const fd=new FormData(e.currentTarget),payload={};for(const [k,v] of fd.entries()){const f=m.fields.find(x=>x.k===k);payload[k]=f?.type==="number"?(v===""?0:Number(v)):v;}const btn=e.submitter;btn.disabled=true;btn.textContent="Saving…";try{await api(item?`/api/${page}/${item.id}`:`/api/${page}`,{method:item?"PATCH":"POST",body:JSON.stringify(payload)});closeModal();toast(item?"Record updated":"Record saved",`${payload.name||"Record"} is saved to your workspace.`);await renderPage(page);loadNotifications();}catch(err){toast("Could not save",err.message,"error");btn.disabled=false;btn.textContent=item?"Save changes →":"Save record →";}});}
  function exportCsv(page){const items=state.data[page]||[];if(!items.length){toast("Nothing to export","Add records before exporting.","warning");return;}const keys=[...new Set(items.flatMap(Object.keys))].filter(k=>!k.startsWith("owner")&&k!=="password_hash");const csv=[keys.join(","),...items.map(x=>keys.map(k=>'"'+String(x[k]??"").replace(/"/g,'""')+'"').join(","))].join("\r\n");downloadBlob(csv,`${page}-rippleguard.csv`,"text/csv;charset=utf-8");}
  function downloadBlob(content,name,type){const blob=content instanceof Blob?content:new Blob([content],{type});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

  function networkHTML(){const suppliers=state.data.suppliers||[],fac=state.data.facilities||[];return `${pageHead("Supply network","Explore your physical footprint and supplier-to-facility relationships.",`<button class="btn btn-outline" id="networkAddFacility">+ Add facility</button><button class="btn btn-primary" id="networkAddSupplier">+ Add supplier</button>`)}<div class="map-layout"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Geographic supply footprint</h3><div class="card-subtitle">Click a pin to inspect a facility or supplier. Add coordinates to place your own locations.</div></div><span class="status-pill">Interactive map</span></div><div id="networkMap" class="map-frame"></div><div class="map-legend"><span class="legend-item"><i class="legend-dot"></i> Supplier</span><span class="legend-item"><i class="legend-dot warn"></i> Facility / warehouse</span><span class="legend-item"><i class="legend-dot critical"></i> Affected supplier</span></div><p class="tiny-note">Map tiles from OpenStreetMap contributors. This is a geographic map, not a live logistics tracking feed.</p></section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Network entities</h3><div class="card-subtitle">${suppliers.length} suppliers · ${fac.length} facilities</div></div></div><div class="map-side-list">${[...suppliers.map(x=>({...x,_kind:"Supplier"})),...fac.map(x=>({...x,_kind:x.type||"Facility"}))].map(x=>`<div class="map-point" data-map-lat="${Number(x.latitude??11.0168)}" data-map-lng="${Number(x.longitude??76.9558)}"><span class="map-pin" style="background:${x._kind==="Supplier"?"var(--teal-deep)":"var(--amber)"}"></span><div><b>${esc(x.name)}</b><small>${esc(x._kind)} · ${esc(x.address||x.category||"Location not provided")}</small></div></div>`).join("")||`<div class="empty-notifications">Add suppliers and facilities to populate the map.</div>`}</div><div class="notice-box" style="margin-top:15px">Tip: use latitude and longitude from the location details. Default coordinates point to Coimbatore and are only a starting example.</div></aside></div>`;}
  function initMap(){const el=$("#networkMap");if(!el||!window.L)return;state.map=L.map(el,{scrollWheelZoom:false}).setView([11.0168,76.9558],5);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap</a> contributors'}).addTo(state.map);const points=[];for(const s of state.data.suppliers||[])points.push({...s,kind:"Supplier",lat:Number(s.latitude??11.0168),lng:Number(s.longitude??76.9558),color:"#218f82"});for(const f of state.data.facilities||[])points.push({...f,kind:f.type||"Facility",lat:Number(f.latitude??11.0168),lng:Number(f.longitude??76.9558),color:"#d79a43"});points.forEach(p=>{if(!Number.isFinite(p.lat)||!Number.isFinite(p.lng))return;const marker=L.circleMarker([p.lat,p.lng],{radius:8,color:p.color,fillColor:p.color,fillOpacity:.88,weight:2}).addTo(state.map);marker.bindPopup(`<b>${esc(p.name)}</b>${esc(p.kind)}<br>${esc(p.address||p.category||"No address")}`);p._marker=marker;});if(points.length){const bounds=L.latLngBounds(points.map(p=>[p.lat,p.lng]));state.map.fitBounds(bounds.pad(.25),{maxZoom:11});}setTimeout(()=>state.map&&state.map.invalidateSize(),100);$$('[data-map-lat]').forEach(el=>el.addEventListener("click",()=>{const lat=Number(el.dataset.mapLat),lng=Number(el.dataset.mapLng);state.map.setView([lat,lng],12,{animate:true});}));}
  function bindNetwork(){$("#networkAddFacility").addEventListener("click",()=>openRecordModal("facilities"));$("#networkAddSupplier").addEventListener("click",()=>openRecordModal("suppliers"));}

  function hbars(rows){const max=Math.max(1,...rows.map(r=>r.value));return `<div class="hbars">${rows.map(r=>`<div class="hbar-row"><span class="hbar-label">${esc(r.label)}</span><div class="hbar-track"><div class="hbar-fill ${r.cls||""}" style="width:${r.value>0?Math.max(4,r.value/max*100):0}%"></div></div><b class="hbar-value">${esc(r.text!==undefined?r.text:fmt(r.value))}</b></div>`).join("")}</div>`}
  function impactHTML(d){const score=d.risk_score||0;const impacted=d.impacted_suppliers||[];const prods=(d.products||[]).map(p=>({label:p.name,value:Math.max(0,Number(p.required_components||0)-Number(p.available_stock||0))})).filter(x=>x.value>0).sort((a,b)=>b.value-a.value).slice(0,6);const ratio=d.total_required?Math.round(Math.min(100,(d.shortage||0)/d.total_required*100)):0;
    return `${pageHead("Impact analysis","See how disruptions affect your supply network.",`<button class="btn btn-primary" id="runImpact">Run analysis ↗</button>`)}<div class="analysis-hero"><div><div class="section-eyebrow">LATEST RESULT</div><h3>${score>=70?"Critical network exposure":score>=35?"Network needs attention":"Network looks stable"}</h3><p>${d.active_disruptions||0} active disruption(s) · ${impacted.length} supplier(s) affected · ${fmt(d.shortage)} units short</p></div><div class="analysis-score">${score}<small>RISK SCORE / 100</small>${riskPill(d.risk_level)}</div></div><div class="metric-grid">${metric("Active disruptions",fmt(d.active_disruptions),"⌁","Currently recorded")}${metric("Suppliers affected",fmt(impacted.length),"⇄","Matched by supplier name")}${metric("Shortage units",fmt(d.shortage),"▦",`Required ${fmt(d.total_required)}`)}${metric("Shortage level",ratio+"%","◔","Of total requirement")}</div><div class="content-grid"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Shortage by product</h3><div class="card-subtitle">Units still needed</div></div></div>${prods.length?hbars(prods):`<div class="empty-notifications">No shortage found.</div>`}</section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Affected suppliers</h3><div class="card-subtitle">From active disruptions</div></div></div>${impacted.length?impacted.map(x=>`<div class="check-item"><span class="check-mark warn">!</span><div><b>${esc(typeof x==="string"?x:(x.name||x.supplier||"Supplier"))}</b></div></div>`).join(""):`<div class="empty-notifications">No supplier affected.</div>`}</aside></div>`;}
  function bindImpact(){$("#runImpact").addEventListener("click",async()=>{try{const d=await api("/api/analysis/run",{method:"POST",body:JSON.stringify({})});state.lastAnalysis=d;toast("Impact analysis complete",`Score ${d.risk_score}/100 · ${d.risk_level}`,d.risk_score>=35?"warning":"success");renderPage("impact");loadNotifications();}catch(e){toast("Analysis failed",e.message,"error")}});}

  function simulatorHTML(){const suppliers=state.data.suppliers||[];const options=suppliers.map(s=>`<option value="${esc(s.name)}">${esc(s.name)} · capacity ${fmt(s.capacity)}</option>`).join("");return `${pageHead("What-if simulator","Test hypothetical failures and inspect shortage impact before choosing a response.",`<button class="btn btn-outline" id="simReset">Reset scenario</button>`)}<div class="content-grid"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Configure a crisis scenario</h3><div class="card-subtitle">Change assumptions; the simulation runs locally from your current workspace data.</div></div><span class="status-pill">Scenario lab</span></div><form id="simForm" class="form-stack"><label class="field-label">Scenario type<select id="simType" class="field-control"><option value="supplier">Supplier stops delivery</option><option value="delay">Delivery delayed</option><option value="stock">Unexpected stock loss</option><option value="route">Transport route closed</option></select></label><label class="field-label">Affected supplier<select id="simSupplier" class="field-control"><option value="">Choose supplier (optional)</option>${options}</select></label><div class="field-label">Supply interruption level<div class="range-row"><input id="simImpact" type="range" min="10" max="100" step="5" value="60"><span class="range-value" id="simImpactValue">60%</span></div><span class="field-help">Percentage of this supplier's daily capacity unavailable in the scenario.</span></div><label class="field-label">Expected duration (days)<input id="simDays" class="field-control" type="number" min="1" max="90" value="3" required></label><label class="field-label">Extra emergency cost per unit (₹)<input id="simCost" class="field-control" type="number" min="0" step="0.5" value="5" required></label><button class="btn btn-primary" type="submit">Run what-if simulation →</button></form></section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Scenario assumptions</h3><div class="card-subtitle">What the result means</div></div></div><div class="check-list"><div class="check-item"><span class="check-mark">1</span><div><b>Capacity exposure</b><p>Estimated lost supply = daily supplier capacity × interruption level × duration.</p></div></div><div class="check-item"><span class="check-mark">2</span><div><b>Stock buffer</b><p>Product stock can absorb some impact, but inventory is not automatically allocated to a specific supplier unless you model that link.</p></div></div><div class="check-item"><span class="check-mark">3</span><div><b>Decision support</b><p>Use the result to explore a scenario, not as a live forecast of a real event.</p></div></div></div></aside></div><div id="simResult" style="margin-top:16px"></div>`;}
  function bindSimulator(){const slider=$("#simImpact");slider.addEventListener("input",()=>$("#simImpactValue").textContent=slider.value+"%");$("#simReset").addEventListener("click",()=>{ $("#simForm").reset();$("#simImpactValue").textContent="60%";$("#simResult").innerHTML="";});$("#simForm").addEventListener("submit",e=>{e.preventDefault();const sup=(state.data.suppliers||[]).find(s=>s.name===$("#simSupplier").value);const products=state.data.products||[];const rate=Number($("#simImpact").value)/100,days=Math.max(1,Number($("#simDays").value)||1),cost=Number($("#simCost").value)||0;const capacity=Number(sup?.capacity||0);const lost=Math.round(capacity*rate*days);const stock=products.reduce((a,p)=>a+Number(p.available_stock||0),0);const required=products.reduce((a,p)=>a+Number(p.required_components||0),0);const stockGap=Math.max(0,required-stock);const projected=Math.max(stockGap,lost);const emergency=projected*cost;const supplierName=sup?.name||"Unspecified supplier";$("#simResult").innerHTML=`<section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Scenario result</h3><div class="card-subtitle">${esc(titleCase($("#simType").value))} · ${esc(supplierName)} · ${days} day(s)</div></div>${riskPill(projected>100?"Critical":projected>0?"Warning":"Stable")}</div><div class="scenario-result"><div class="scenario-metric"><small>Estimated lost supply</small><b>${fmt(lost)}</b></div><div class="scenario-metric"><small>Current stock gap</small><b>${fmt(stockGap)}</b></div><div class="scenario-metric"><small>Illustrative extra cost</small><b>${money(emergency)}</b></div></div>${hbars([{label:"Lost supply",value:lost,cls:"red"},{label:"Stock gap",value:stockGap,cls:"amber"},{label:"Projected exposure",value:projected}])}<div class="notice-box amber" style="margin-top:14px">This is a what-if estimate based on the values entered, not an automatic live forecast. Continue to Recovery Planner to compare suppliers.</div><div class="form-actions"><button class="btn btn-primary" id="goRecovery">Plan a recovery →</button></div></section>`;$("#goRecovery").addEventListener("click",()=>{navigate("recovery");setTimeout(()=>{const sh=$("#recoveryShortage");if(sh)sh.value=String(projected);},80);});toast("Scenario simulated","Review the calculated exposure and assumptions.","success");});}

  function recoveryHTML(){const products=state.data.products||[];const totalReq=products.reduce((a,p)=>a+Number(p.required_components||0),0),totalStock=products.reduce((a,p)=>a+Number(p.available_stock||0),0),gap=Math.max(0,totalReq-totalStock);return `${pageHead("Recovery planner","Compare supplier options against shortage, budget, capacity, and delivery deadline.",`<button class="btn btn-outline" id="recoveryUseStock">Use calculated shortage</button>`)}<div class="content-grid"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Define recovery requirements</h3><div class="card-subtitle">The planner checks supplier capacity, unit cost, lead time, and reliability.</div></div></div><form id="recoveryForm" class="form-stack"><label class="field-label">Quantity required to recover<input id="recoveryShortage" class="field-control" type="number" min="0" step="1" value="${gap}" required></label><label class="field-label">Maximum recovery budget (₹)<input id="recoveryBudget" class="field-control" type="number" min="0" step="1" value="10000" required></label><label class="field-label">Required delivery within (days)<input id="recoveryDeadline" class="field-control" type="number" min="0" max="365" value="7" required></label><label class="field-label">Optimization priority<select id="recoveryPriority" class="field-control"><option value="balanced">Balanced: feasibility, cost, time, reliability</option><option value="cost">Lowest cost first</option><option value="speed">Fastest delivery first</option><option value="reliability">Highest reliability first</option></select></label><button class="btn btn-primary" type="submit">Find recovery options →</button></form><div class="tiny-note">This starter planner evaluates each supplier individually. The advanced version can use OR-Tools for multi-supplier allocation.</div></section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Decision constraints</h3><div class="card-subtitle">Every option is checked against</div></div></div><div class="chip-row"><span class="chip">Capacity</span><span class="chip">Budget</span><span class="chip">Deadline</span><span class="chip">Remaining shortage</span></div></aside></div><div id="recoveryResult" style="margin-top:16px"></div>`;}
  function bindRecovery(){ $("#recoveryUseStock").addEventListener("click",()=>{$("#recoveryShortage").value=String(Math.max(0,(state.data.products||[]).reduce((a,p)=>a+Number(p.required_components||0),0)-(state.data.products||[]).reduce((a,p)=>a+Number(p.available_stock||0),0)));toast("Shortage loaded","Calculated from current product stock.")});$("#recoveryForm").addEventListener("submit",async e=>{e.preventDefault();const payload={shortage:Number($("#recoveryShortage").value),budget:Number($("#recoveryBudget").value),deadline_days:Number($("#recoveryDeadline").value)};try{const d=await api("/api/recovery/plan",{method:"POST",body:JSON.stringify(payload)});const priority=$("#recoveryPriority").value;if(priority==="cost")d.candidates.sort((a,b)=>a.total_cost-b.total_cost);if(priority==="speed")d.candidates.sort((a,b)=>a.lead_days-b.lead_days);if(priority==="reliability")d.candidates.sort((a,b)=>b.reliability-a.reliability);state.lastPlan=d;$("#recoveryResult").innerHTML=recoveryResultHTML(d);bindRecoveryResult();toast("Recovery options ready",d.status,d.status==="Feasible"?"success":"warning");loadNotifications();}catch(err){toast("Planner failed",err.message,"error")}});}
  function recoveryResultHTML(d){return `<section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Recovery recommendation</h3><div class="card-subtitle">${esc(d.explanation)}</div></div>${riskPill(d.status==="Feasible"?"Stable":d.status==="Partially feasible"?"Warning":"Critical")}</div><div class="scenario-result"><div class="scenario-metric"><small>Requested quantity</small><b>${fmt(d.requested_shortage)}</b></div><div class="scenario-metric"><small>Remaining shortage</small><b>${fmt(d.remaining_shortage)}</b></div><div class="scenario-metric"><small>Feasible suppliers</small><b>${d.candidates.filter(x=>x.feasible).length}</b></div></div>${d.candidates.length?`<div style="margin-top:18px">${hbars(d.candidates.slice(0,6).map(c=>({label:c.supplier,value:Number(c.total_cost||0),text:money(c.total_cost),cls:c.feasible?"":"red"})))}</div>`:""}<div style="margin-top:18px"><div class="card-head"><div><h3 class="card-title">Supplier comparison</h3><div class="card-subtitle">The highlighted option is the current selected candidate.</div></div></div>${d.candidates.length?d.candidates.map((c,i)=>`<div class="candidate-card ${d.selected&&c.supplier_id===d.selected.supplier_id?"selected":""}"><div><h4>${esc(c.supplier)} ${d.selected&&c.supplier_id===d.selected.supplier_id?'<span class="status-pill">Selected</span>':""}</h4><p>Capacity ${fmt(c.capacity)} · Lead time ${fmt(c.lead_days)} days · Reliability ${fmt(c.reliability)}%<br>${esc(c.reason||"")}</p></div><div class="candidate-cost"><b>${money(c.total_cost)}</b><small>${c.feasible?"Feasible":"Not feasible"}</small></div></div>`).join(""):`<div class="empty-notifications">No suppliers with usable capacity. Add supplier capacity and cost, then retry.</div>`}</div><div class="form-actions"><button class="btn btn-outline" id="recoveryExportCsv">Export comparison CSV</button><button class="btn btn-primary" id="validatePlan">Validate this plan →</button></div></section>`;}
  function bindRecoveryResult(){$("#recoveryExportCsv").addEventListener("click",()=>{const d=state.lastPlan;const rows=[["Supplier","Capacity","Unit cost","Lead days","Reliability","Quantity","Total cost","Feasible","Reason"],...(d?.candidates||[]).map(c=>[c.supplier,c.capacity,c.unit_cost,c.lead_days,c.reliability,c.quantity,c.total_cost,c.feasible,c.reason])];downloadBlob(rows.map(r=>r.map(v=>'"'+String(v??"").replace(/"/g,'""')+'"').join(",")).join("\r\n"),"recovery-options.csv","text/csv");});$("#validatePlan").addEventListener("click",()=>navigate("validation"));}
  function validationHTML(){const p=state.lastPlan;return `${pageHead("Plan validation","Independently check whether a recovery recommendation meets the declared constraints.",`<button class="btn btn-outline" id="validationReports">Open reports →</button>`)}${p?`<div class="analysis-hero"><div><div class="section-eyebrow">PLAN UNDER REVIEW</div><h3>${esc(p.selected?.supplier||"No supplier selected")}</h3><p>Requested ${fmt(p.requested_shortage)} units · Budget ${money(p.budget)} · Deadline ${fmt(p.deadline_days)} days. Validation below uses the saved planner result.</p></div><div class="analysis-score">${p.remaining_shortage===0&&p.selected?"PASS":"REVIEW"}<small>VALIDATION STATUS</small></div></div><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Constraint checklist</h3><div class="card-subtitle">Every failed condition is displayed explicitly</div></div></div><div class="check-list">${validationItems(p).map(x=>`<div class="check-item"><span class="check-mark ${x.ok?"":"warn"}">${x.ok?"✓":"!"}</span><div><b>${esc(x.title)}</b><p>${esc(x.detail)}</p></div></div>`).join("")}</div><div class="notice-box ${p.remaining_shortage?"amber":""}" style="margin-top:16px">${p.remaining_shortage===0&&p.selected?"The selected single-supplier option covers the requested quantity within the constraints checked by this prototype.":"This plan is not fully feasible. Consider a different supplier, more budget, a longer deadline, or a multi-supplier allocation."}</div><div class="form-actions"><button class="btn btn-outline" id="validationNewPlan">Change plan</button><button class="btn btn-primary" id="validationDownload">Download PDF report</button></div></section>`:`<section class="card card-pad"><h3 class="card-title">No recovery plan to validate yet</h3><p class="muted">Run the Recovery Planner first. The selected option and its constraints will appear here.</p><button class="btn btn-primary" id="startPlanner">Open recovery planner →</button></section>`}`;}
  function validationItems(p){const s=p.selected;return [{title:"Supplier selected",ok:!!s,detail:s?`Selected supplier: ${s.supplier}.`:"No supplier satisfies the current filter."},{title:"Capacity check",ok:!!s&&s.quantity<=s.capacity,detail:s?`Planned quantity ${fmt(s.quantity)} ≤ capacity ${fmt(s.capacity)}.`:"Cannot validate capacity without a supplier."},{title:"Budget check",ok:!!s&&s.total_cost<=p.budget,detail:s?`Plan cost ${money(s.total_cost)} against budget ${money(p.budget)}.`:"No plan cost available."},{title:"Delivery deadline",ok:!!s&&s.lead_days<=p.deadline_days,detail:s?`Lead time ${s.lead_days} day(s); deadline ${p.deadline_days} day(s).`:"No lead time available."},{title:"Quantity coverage",ok:!!s&&p.remaining_shortage===0,detail:`Requested ${fmt(p.requested_shortage)}; planned ${fmt(s?.quantity||0)}; remaining shortage ${fmt(p.remaining_shortage)}.`},{title:"Side-effect limitation",ok:false,detail:"This prototype checks the selected supplier's declared constraints. It does not yet simulate every other factory's inventory unless explicit product-to-factory allocation links are added."}];}
  function bindValidation(){const b=$("#startPlanner");if(b)b.addEventListener("click",()=>navigate("recovery"));const c=$("#validationNewPlan");if(c)c.addEventListener("click",()=>navigate("recovery"));const r=$("#validationReports");if(r)r.addEventListener("click",()=>navigate("reports"));const d=$("#validationDownload");if(d)d.addEventListener("click",()=>downloadReport("pdf"));}

  function reportsHTML(items){return `${pageHead("Reports & history","Export current risk summaries and review previous analysis runs.",`<button class="btn btn-primary" id="reportsRun">Generate current report →</button>`)}<section class="card card-pad" style="margin-bottom:16px"><div class="card-head"><div><h3 class="card-title">Export report</h3><div class="card-subtitle">Download a workspace snapshot as PDF, Word, or CSV.</div></div></div><div class="report-actions"><button class="report-option" data-report="pdf"><span class="report-icon">▤</span><b>PDF risk report</b><p>Readable summary with counts, shortage, risk and active disruptions.</p></button><button class="report-option" data-report="docx"><span class="report-icon">W</span><b>Word document</b><p>Editable report suitable for adding project-specific notes.</p></button><button class="report-option" data-report="csv"><span class="report-icon">▦</span><b>CSV snapshot</b><p>Compact text data for spreadsheets and quick review.</p></button></div></section><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Analysis history</h3><div class="card-subtitle">Most recent analyses saved by this workspace</div></div><span class="status-pill">${items.length} record(s)</span></div><div class="table-wrap"><table><thead><tr><th>Run time</th><th>Analysis type</th><th>Risk score</th><th>Shortage</th><th>Risk level</th></tr></thead><tbody>${items.length?items.map(x=>`<tr><td>${esc(new Date(x.created_at||Date.now()).toLocaleString())}</td><td>${esc(x.kind||"Impact analysis")}</td><td>${fmt(x.risk_score||0)}/100</td><td>${fmt(x.shortage||0)}</td><td>${riskPill(x.risk_level||x.result?.status||"Saved")}</td></tr>`).join(""):emptyRow(5,"No saved analysis yet. Run an impact analysis to create history.")}</tbody></table></div></section>`;}
  function bindReports(){$$("[data-report]").forEach(b=>b.addEventListener("click",()=>downloadReport(b.dataset.report)));$("#reportsRun").addEventListener("click",async()=>{try{const d=await api("/api/analysis/run",{method:"POST",body:JSON.stringify({})});toast("Report data refreshed",`Current risk score: ${d.risk_score}/100`);renderPage("reports");}catch(e){toast("Could not generate report",e.message,"error")}});}
  async function downloadReport(type){try{const response=await fetch(`${API}/api/reports/export?type=${encodeURIComponent(type)}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let d={};try{d=await response.json()}catch(_){}throw new Error(d.error||`Export failed (${response.status})`)}const blob=await response.blob();const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`rippleguard-report.${type==="docx"?"docx":type}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Report downloaded",`Your ${type.toUpperCase()} report is ready.`);}catch(e){toast("Export failed",e.message,"error")}}


  function productionHTML(){const orders=state.data.orders||[],steps=state.data.process_steps||[];const selected=orders.find(o=>o.id===state.selectedOrderId)||orders[0];if(selected)state.selectedOrderId=selected.id;const current=selected?steps.filter(s=>String(s.order_id)===selected.id).sort((a,b)=>String(a.started_at||"").localeCompare(String(b.started_at||""))):[];return `${pageHead("Production journey","Track each product from sourcing to completion with supplier, date, time, and location records.",`<button class="btn btn-outline" id="addJourneyStep" ${selected?"":"disabled"}>+ Add process step</button><button class="btn btn-primary" id="addJourneyOrder">+ Create product order</button>`)}<div class="content-grid"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Product journey timeline</h3><div class="card-subtitle">Choose an order to inspect its traceable process history.</div></div></div>${orders.length?`<label class="field-label" style="margin-bottom:16px">Select order<select id="journeyOrderSelect" class="field-control">${orders.map(o=>`<option value="${esc(o.id)}" ${o.id===selected.id?"selected":""}>${esc(o.order_no||o.name)} · ${esc(o.status||"Open")}</option>`).join("")}</select></label><div class="analysis-hero"><div><div class="section-eyebrow">ORDER ${esc(selected.order_no||selected.id.slice(0,8))}</div><h3>${esc(selected.name||"Product order")}</h3><p>Quantity ${fmt(selected.quantity)} · Supplier ${esc(selected.supplier||"Not assigned")} · Start ${esc(selected.start_date||"Not recorded")} · Due ${esc(selected.due_date||"Not recorded")}</p></div><div>${riskPill(selected.status||"Open")}</div></div><div class="result-tree">${current.length?current.map((s,i)=>`<div class="tree-node" style="cursor:default"><span class="tree-number">${String(i+1).padStart(2,"0")}</span><div style="flex:1"><b>${esc(s.stage||s.name)}</b><small>${esc(s.supplier||"Supplier not recorded")} · ${esc(s.location||"Location not recorded")}</small><small>Started: ${esc(s.started_at||"—")} · Completed: ${esc(s.completed_at||"Not completed")}</small><small>${esc(s.notes||"")}</small></div><div>${riskPill(s.status||"In progress")}</div></div>${i<current.length-1?`<span class="tree-connector"></span>`:""}`).join(""):`<div class="empty-notifications">No process steps yet. Add the first step, such as supplier confirmation or material receipt.</div>`}</div><div class="form-actions"><button class="btn btn-outline" id="journeyReportPdf">Export PDF</button><button class="btn btn-outline" id="journeyReportDocx">Export Word</button><button class="btn btn-primary" id="completeOrder">Mark order complete ✓</button></div>`:`<div class="empty-notifications">Create a product order to start its traceable journey.</div>`}</section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Journey checkpoints</h3><div class="card-subtitle">Suggested stages; enter only the stages relevant to your product.</div></div></div><div class="check-list">${[{t:"1. Source materials",d:"Select supplier and record order placement."},{t:"2. Material dispatch",d:"Record dispatch date, time, supplier and origin."},{t:"3. Material received",d:"Record receiving location and quantity status."},{t:"4. Manufacturing",d:"Record production start and completion."},{t:"5. Quality check",d:"Add inspection outcome and notes."},{t:"6. Final delivery",d:"Record final location, date and time."}].map((x,i)=>`<div class="check-item"><span class="check-mark">${i+1}</span><div><b>${x.t}</b><p>${x.d}</p></div></div>`).join("")}</div><div class="notice-box" style="margin-top:15px">Every process step is saved as a separate record. The final report contains the order summary and its timeline.</div></aside></div>`;}
  function bindProduction(){const addOrder=$("#addJourneyOrder");addOrder.addEventListener("click",openOrderModal);const addStep=$("#addJourneyStep");if(addStep)addStep.addEventListener("click",openStepModal);const sel=$("#journeyOrderSelect");if(sel)sel.addEventListener("change",()=>{state.selectedOrderId=sel.value;renderPage("production")});const pdf=$("#journeyReportPdf");if(pdf)pdf.addEventListener("click",()=>downloadOrderReport("pdf"));const docx=$("#journeyReportDocx");if(docx)docx.addEventListener("click",()=>downloadOrderReport("docx"));const complete=$("#completeOrder");if(complete)complete.addEventListener("click",async()=>{const o=(state.data.orders||[]).find(x=>x.id===state.selectedOrderId);if(!o)return;try{await api(`/api/orders/${o.id}`,{method:"PATCH",body:JSON.stringify({status:"Completed",completed_at:new Date().toISOString()})});toast("Order completed","The final status was saved to the order.");await loadAll();renderPage("production");}catch(e){toast("Could not complete order",e.message,"error")}});}
  function openOrderModal(){const body=`<form id="journeyOrderForm"><div class="form-grid">${fieldHTML({k:"order_no",l:"Order ID",req:1,placeholder:"RG-ORD-1003"})}${fieldHTML({k:"name",l:"Product / batch name",req:1})}${fieldHTML({k:"quantity",l:"Quantity",type:"number",req:1})}${fieldHTML({k:"supplier",l:"Primary supplier",type:"select",options:["Not assigned",...(state.data.suppliers||[]).map(s=>s.name)]})}${fieldHTML({k:"start_date",l:"Start date",type:"datetime-local",req:1})}${fieldHTML({k:"due_date",l:"Target completion date",type:"date",req:1})}${fieldHTML({k:"location",l:"Starting location",placeholder:"City / facility"})}${fieldHTML({k:"status",l:"Status",type:"select",options:["Open","In progress","At risk","Completed"]})}</div><div class="form-actions"><button type="button" class="btn btn-outline" id="cancelOrder">Cancel</button><button type="submit" class="btn btn-primary">Create order →</button></div></form>`;openModal("Create product order","Start a product's end-to-end traceability record",body);$("#cancelOrder").addEventListener("click",closeModal);$("#journeyOrderForm").addEventListener("submit",async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());payload.quantity=Number(payload.quantity||0);try{const d=await api("/api/orders",{method:"POST",body:JSON.stringify(payload)});state.selectedOrderId=d.item.id;closeModal();await loadAll();renderPage("production");toast("Order created","Add process steps to track its journey.");loadNotifications();}catch(err){toast("Could not create order",err.message,"error")}});}
  function openStepModal(){const order=(state.data.orders||[]).find(o=>o.id===state.selectedOrderId);if(!order)return;const body=`<form id="journeyStepForm"><div class="form-grid">${fieldHTML({k:"stage",l:"Process stage",type:"select",req:1,options:["Supplier confirmation","Material dispatch","Material received","Manufacturing started","Manufacturing completed","Quality inspection","Packaging","Final delivery","Other"]})}${fieldHTML({k:"supplier",l:"Supplier / handler",type:"select",options:["Not assigned",...(state.data.suppliers||[]).map(s=>s.name)]})}${fieldHTML({k:"location",l:"Location",req:1,placeholder:"Warehouse, factory, city"})}${fieldHTML({k:"started_at",l:"Start date and time",type:"datetime-local",req:1})}${fieldHTML({k:"completed_at",l:"Completion date and time",type:"datetime-local"})}${fieldHTML({k:"status",l:"Stage status",type:"select",options:["In progress","Completed","Delayed","Blocked"]})}${fieldHTML({k:"notes",l:"Notes / evidence",type:"textarea",full:1})}</div><div class="form-actions"><button type="button" class="btn btn-outline" id="cancelStep">Cancel</button><button type="submit" class="btn btn-primary">Save process step →</button></div></form>`;openModal("Add process step",`Order: ${order.order_no||order.name}`,body);$("#cancelStep").addEventListener("click",closeModal);$("#journeyStepForm").addEventListener("submit",async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(e.currentTarget).entries());payload.name=payload.stage;payload.order_id=order.id;try{await api("/api/process_steps",{method:"POST",body:JSON.stringify(payload)});closeModal();await loadAll();renderPage("production");toast("Process step saved",`${payload.stage} was added to the timeline.`);loadNotifications();}catch(err){toast("Could not save step",err.message,"error")}});}
  async function downloadOrderReport(type){const id=state.selectedOrderId;if(!id){toast("Select an order","Create or select an order first.","warning");return;}try{const response=await fetch(`${API}/api/orders/${id}/report?type=${type}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!response.ok){let d={};try{d=await response.json()}catch(_){}throw new Error(d.error||"Report export failed");}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`rippleguard-product-journey.${type==="docx"?"docx":type}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Product report downloaded",`${type.toUpperCase()} journey report is ready.`);}catch(e){toast("Export failed",e.message,"error")}}

  function settingsHTML(){return `${pageHead("Workspace settings","Manage workspace details, account information, and notification preferences.") }<div class="content-grid"><section class="card card-pad"><div class="card-head"><div><h3 class="card-title">Workspace profile</h3><div class="card-subtitle">Your current registered account</div></div><span class="status-pill">Verified account</span></div><div class="setting-row"><div><b>Workspace / company</b><small>${esc(state.user?.company||"—")}</small></div></div><div class="setting-row"><div><b>Account name</b><small>${esc(state.user?.name||"—")}</small></div></div><div class="setting-row"><div><b>Registered email</b><small>${esc(state.user?.email||"—")}</small></div></div><div class="setting-row"><div><b>Phone</b><small>${esc(state.user?.phone||"—")}</small></div></div><div class="setting-row"><div><b>Workspace role</b><small>${esc(state.user?.role||"—")}</small></div></div><div class="setting-row"><div><b>Notification sounds</b><small>Play a subtle sound when the app displays a toast message.</small></div><label class="switch"><input id="settingsSound" type="checkbox" ${state.sound?"checked":""}><span></span></label></div></section><aside class="card card-pad"><div class="card-head"><div><h3 class="card-title">Deployment readiness</h3><div class="card-subtitle">Before sharing the live website</div></div></div><div class="check-list"><div class="check-item"><span class="check-mark">✓</span><div><b>Workspace isolation</b><p>Records are scoped to the signed-in account in the API.</p></div></div><div class="check-item"><span class="check-mark warn">!</span><div><b>Replace development secrets</b><p>Set a strong SECRET_KEY and your MongoDB Atlas connection string on Render.</p></div></div><div class="check-item"><span class="check-mark warn">!</span><div><b>Real SMS OTP</b><p>Current OTP is demo-only. Integrate and test an SMS provider before production use.</p></div></div><div class="check-item"><span class="check-mark warn">!</span><div><b>Live data integrations</b><p>Map pins use entered coordinates. Live supplier, weather, and route feeds are not connected.</p></div></div></div><div class="notice-box" style="margin-top:15px">Prototype security checklist is not a substitute for a professional production security review.</div></aside></div>`;}
  function bindSettings(){ $("#settingsSound").addEventListener("change",e=>{state.sound=e.target.checked;$("#soundToggle").style.color=state.sound?"var(--teal-deep)":"#a0aab1";toast("Preference saved",state.sound?"Notification sounds enabled.":"Notification sounds muted.")}); }

  function openModal(title,subtitle,body,actions=[]){const root=$("#modalRoot");root.innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h3>${esc(title)}</h3><p>${esc(subtitle||"")}</p></div><button class="modal-close" id="modalClose" aria-label="Close">×</button></div><div class="modal-body">${body}</div>${actions.length?`<div class="modal-foot">${actions.map((a,i)=>`<button class="btn ${a.primary?"btn-primary":"btn-outline"}" data-modal-action="${i}">${esc(a.label)}</button>`).join("")}</div>`:""}</div></div>`;$("#modalClose").addEventListener("click",closeModal);$("#modalBackdrop").addEventListener("click",e=>{if(e.target.id==="modalBackdrop")closeModal()});actions.forEach((a,i)=>$(`[data-modal-action="${i}"]`).addEventListener("click",()=>a.onClick?a.onClick():closeModal()));}
  function closeModal(){$("#modalRoot").innerHTML="";}

  // Session restore. No seeded company data is inserted: every result comes from user-entered records.
  async function init(){if(state.token){try{const d=await api("/api/auth/me");enterApp(d.user);return;}catch(_){sessionStorage.removeItem("rg_token");sessionStorage.removeItem("rg_user");state.token=null;}}showAuth("login");try{const d=await fetch(`${API}/api/health`).then(r=>r.json());if(d.database&&d.database.includes("Local demo memory"))setTimeout(()=>toast("Demo storage mode","Configure MongoDB Atlas to persist data between restarts.","warning"),500);}catch(_){}}
  // ---- Live updates (all roles see each other's changes), sound and voice ----
  state.voice = sessionStorage.getItem("rg_voice") !== "off";
  let liveTimer = null, seenIds = null;
  function speak(text){if(!state.voice||!("speechSynthesis" in window))return;try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=1;u.lang="en-IN";window.speechSynthesis.speak(u);}catch(_){}}
  function pageIsIdle(){const a=document.activeElement;return !$("#modalRoot").children.length&&!(a&&["INPUT","SELECT","TEXTAREA"].includes(a.tagName));}
  async function pollLive(){if(!state.token)return;try{const d=await api("/api/notifications");const items=d.items||[];const ids=new Set(items.map(n=>n.id));if(seenIds===null){seenIds=ids;return;}const added=items.filter(n=>!seenIds.has(n.id));seenIds=ids;if(added.length)await loadNotifications();const fresh=added.filter(n=>n.actor!==state.user?.id);if(fresh.length){const n=fresh[0];toast(n.title,n.message,n.level==="warning"?"warning":"success");speak(`${n.title}. ${n.message}`);if(["dashboard","network","suppliers","facilities","products","disruptions","impact","reports"].includes(state.page)&&pageIsIdle())renderPage(state.page);}}catch(_){}}
  function startLive(){stopLive();seenIds=null;pollLive();liveTimer=setInterval(pollLive,6000);}
  function stopLive(){if(liveTimer)clearInterval(liveTimer);liveTimer=null;}
  const voiceBtn=$("#voiceToggle");if(voiceBtn){const paint=()=>voiceBtn.classList.toggle("muted-btn",!state.voice);paint();voiceBtn.addEventListener("click",()=>{state.voice=!state.voice;sessionStorage.setItem("rg_voice",state.voice?"on":"off");paint();toast("Voice alerts",state.voice?"Voice is on.":"Voice is off.");if(state.voice)speak("Voice alerts on");});}
  init();
})();
